warehouseRpc=async function(fn,a={},...rest){if(fn==='advacon_expiry_execute'){const k={admin_issue:'ISSUE',request_issue_approval:'ISSUE',admin_receive_stock:'RECEIPT',request_receipt_approval:'RECEIPT',admin_return:'RETURN',request_return_approval:'RETURN',admin_transfer_stock:'TRANSFER',request_transfer_approval:'TRANSFER',admin_adjustment:'ADJUSTMENT',request_adjustment_approval:'ADJUSTMENT',admin_disposal:'DISPOSAL',request_disposal_approval:'DISPOSAL'}[a.p_function];if(k){const options=await raw('advacon_warehouse_document_options',{p_kind:k}),lines=a.p_allocations?.length?a.p_allocations.map(p=>({...a.p_args,p_qty:p.qty,p_batch_no:p.batch_no})):[a.p_args],result=await reviewLines(k,lines,options);if(!result)throw Error(tr('أُلغيت العملية.','Operation cancelled.'));return result;}}return raw(fn,a,...rest);};
if(typeof aprLoadBadge==='function')aprLoadBadge=async function(){if(!CTX.mode)return;const owner=CTX.mode+':'+currentUser();const results=await Promise.allSettled([raw('movement_approvals_list',{p_status:'pending'}),raw('advacon_warehouse_documents',{p_status:'pending'})]);if(owner!==CTX.mode+':'+currentUser())return;aprPendingCount=results.reduce((n,r)=>n+(r.status==='fulfilled'?(Array.isArray(r.value)?r.value.length:Number(r.value?.total)||0):0),0);renderSidebar();};
const originalMoveView=viewMovements;viewMovements=function(){const original=originalMoveView();if(!whDirect('movements.view'))return original;const template=document.createElement('template');template.innerHTML=original;const modals=[...template.content.querySelectorAll('.mv-scrim,.mv-modal')].map(n=>{const s=n.outerHTML;n.remove();return s;}).join('');const title=template.content.querySelector('.dash-head');title?.remove();return list('movements')+'<details class="wd-ledger"><summary>'+tr('سجل حركة كل صنف بالتفصيل','Detailed item movement ledger')+'</summary>'+template.innerHTML+'</details>'+modals;};
const originalApprovals=viewApprovals;viewApprovals=function(){return list('approvals')+originalApprovals();};
