const oldPick=mvIsPickItem;mvIsPickItem=function(row){if(form?.kind==='ISSUE'){Promise.resolve(formPromise).then(()=>{if(form?.options){form.query=row.item_code||'';renderForm(form);}});return;}return oldPick(row);};
