const oldRequest=aprOpenReq;aprOpenReq=function(kind){if(kinds[kind]){aprModal=null;aprRender();return openForm(kind);}return oldRequest(kind);};
document.addEventListener('click',e=>{if(e.target.closest('[data-wd-custody]'))openCustody();});
document.addEventListener('change',e=>{if(e.target.matches('[data-wd-filter]')){filter[e.target.dataset.wdFilter]=e.target.value;filter.offset=0;repaint();}});
document.addEventListener('keydown',e=>{if(e.target.id==='wd-query'&&e.key==='Enter'){filter.q=e.target.value;filter.offset=0;repaint();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-wd-open],[data-wd-refresh],[data-wd-search],[data-wd-page]');if(!b)return;if(b.dataset.wdOpen)openDocument(b.dataset.wdOpen);else if(b.hasAttribute('data-wd-search')){filter.q=document.getElementById('wd-query')?.value||'';filter.offset=0;repaint();}else if(b.dataset.wdRefresh)loadList(b.dataset.wdRefresh,true);else if(b.dataset.wdPage){if(b.dataset.wdMode==='approvals')approvalPage=Math.max(0,approvalPage+50*Number(b.dataset.wdPage));else filter.offset=Math.max(0,filter.offset+50*Number(b.dataset.wdPage));repaint();}});
const originalDocumentHTML=documentHTML;
documentHTML=function(data){const d=data.document;let html=originalDocumentHTML(data);const due=(data.custody||[]).find(x=>x.outstanding>0)?.return_due_date||d.return_due_date;
 const extra='<div>'+tr('الموظف','Employee')+'<strong>'+h(name(d.employee_snapshot))+'</strong></div>'+(d.kind==='ISSUE'?'<div>'+tr('موعد الإرجاع الحالي للسند','Current voucher return date')+'<strong>'+h(due||tr('دون موعد إرجاع','No return date'))+'</strong></div>':'');
 html=html.replace('<div class="wd-voucher-meta">','<div class="wd-voucher-meta">'+extra);
 if(d.extension_of){html=html.replace(h(label(d.kind))+' — '+tr('سند مخزون','Stock voucher'),tr('سند تمديد عهدة','Custody extension voucher'));html=html.replace('</header>','</header><p class="wd-extension-note">'+tr('تمديد لسند الصرف رقم ','Extension of issue voucher ')+h(data.extension_root_number||data.extension_parent_number)+' · '+tr('السند السابق: ','Previous voucher: ')+h(data.extension_parent_number)+'<br>'+tr('توثيق موعد الإرجاع الجديد فقط؛ دون صرف كميات إضافية.','Records the new return date only; no additional stock is issued.')+'</p>');}
 if(!d.extension_of&&d.kind==='ISSUE'&&data.custody?.length)html=html.replace('<footer class="wd-signatures">','<h2>'+tr('متابعة الكميات','Quantity follow-up')+'</h2>'+custodyTable(data.custody,false)+'<footer class="wd-signatures">');
 if(data.extensions?.length)html=html.replace('<footer class="wd-signatures">','<h2>'+tr('سجل التمديد','Extension history')+'</h2><ul>'+data.extensions.map(e=>'<li>'+h(e.number)+' · '+h(e.date)+' · '+h(status(e.status))+'</li>').join('')+'</ul><footer class="wd-signatures">');
 return html;};
function custodyTable(rows,actions=true){return '<div class="wd-table wd-custody-table"><table><thead><tr>'+[tr('السند / الصنف','Voucher / item'),tr('الموظف','Employee'),tr('المصروف','Issued'),tr('المرتجع','Returned'),tr('المتبقي','Outstanding'),tr('موعد الإرجاع','Return date')].map(v=>'<th>'+v+'</th>').join('')+'</tr></thead><tbody>'+rows.map(c=>'<tr><td>'+(actions?'<button class="wd-link" data-wd-open="'+h(c.document_id)+'">'+h(c.number)+'</button>':h(c.number))+'<br><b>'+h(c.item.code)+'</b> '+h(name(c.item))+(c.returns?.length?'<small>'+c.returns.map(r=>h(r.number||'')+' · '+h(r.qty)+' · '+h(dateText(r.date))).join('<br>')+'</small>':'')+'</td><td>'+h(name(c.employee))+'</td><td>'+h(c.issued)+'</td><td>'+h(c.returned)+'</td><td><b>'+h(c.outstanding)+'</b></td><td>'+h(c.return_due_date||tr('دون موعد','No due date'))+(actions&&c.return_due_date&&Number(c.outstanding)>0&&whCan('movements.issue')?'<br><button class="wd-link" data-wd-extend="'+h(c.document_id)+'">'+tr('تمديد السند','Extend voucher')+'</button>':'')+'</td></tr>').join('')+'</tbody></table></div>';}
async function openCustody(employeeId){const body=document.createElement('div');body.className='wd-form';const footer=document.createElement('div');footer.className='wd-actions';let closed=false,seq=0;
 const modal=AdvaconUI.modal({title:tr('سجل عهد الموظفين','Employee custody register'),body,footer,wide:true,onClose:()=>{closed=true;seq++;}});body.textContent=tr('جارٍ التحميل…','Loading…');
 try{if(!employeeOptions.length){const o=await raw('advacon_warehouse_documents_v2',{p_offset:0});employeeOptions=o.employees||[];}if(closed)return;body.innerHTML='<label>'+tr('الموظف','Employee')+'<input data-custody-find type="search" placeholder="'+tr('ابحث بالاسم','Search by name')+'"><select data-custody-employee>'+selectHTML(employeeOptions,employeeId||'',tr('كل الموظفين','All employees'))+'</select></label><div data-custody-content></div>';body.querySelector('[data-custody-find]').oninput=e=>{const q=e.target.value.trim().toLowerCase(),value=body.querySelector('select').value;body.querySelector('select').innerHTML=selectHTML(employeeOptions.filter(x=>x.id===value||name(x).toLowerCase().includes(q)),value,tr('كل الموظفين','All employees'));};
 async function load(){const rev=++seq,id=body.querySelector('select').value,target=body.querySelector('[data-custody-content]');target.textContent=tr('جارٍ التحميل…','Loading…');footer.innerHTML='';try{const r=await raw('advacon_warehouse_custody',{p_employee_id:id||null,p_warehouse_id:null,p_due:null});if(closed||rev!==seq)return;const rows=r.items||[];target.innerHTML=rows.length?[true,false].map(due=>{const group=rows.filter(c=>!!c.return_due_date===due);return '<h3>'+tr(due?'عهد بموعد إرجاع':'مواد دون موعد إرجاع',due?'Custody with a return date':'Items without a return date')+'</h3>'+(group.length?custodyTable(group):'<p>'+tr('لا توجد مواد.','No items.')+'</p>');}).join(''):'<p>'+tr('لا توجد مواد مسجلة لهذا الاختيار.','No issued items match this selection.')+'</p>';if(id&&whCan('movements.return'))footer.append(btn(tr('إرجاع مواد الموظف','Return employee items'),async()=>{modal.close();await openForm('RETURN');if(form?.kind==='RETURN'){form.employee=id;await loadCustody(form);}},true));}catch(e){if(!closed&&rev===seq)target.textContent=friendly(e);}}
 body.querySelector('select').onchange=load;body.onclick=e=>{const b=e.target.closest('[data-wd-extend]');if(b){e.stopPropagation();modal.close();extendCustody(b.dataset.wdExtend);}};await load();
 }catch(e){if(!closed)body.textContent=friendly(e);}}
async function extendCustody(id){try{const data=await raw('advacon_warehouse_document_get_v2',{p_id:id}),rows=(data.custody||[]).filter(c=>Number(c.outstanding)>0);if(!rows.length)throw Error('custody_already_returned');const current=rows[0].return_due_date;if(!current)throw Error('not_returnable_custody');const body=document.createElement('div'),footer=document.createElement('div');body.className='wd-form';body.innerHTML='<p>'+tr('تمديد لسند الصرف رقم ','Extension of issue voucher ')+h(rows[0].number)+'</p><p>'+tr('الموعد الحالي: ','Current due date: ')+h(current)+'</p><label>'+tr('موعد الإرجاع الجديد للسند كاملًا','New return date for the entire voucher')+'<input type="date" required></label><label>'+tr('ملاحظة','Note')+'<textarea></textarea></label><p class="wd-error" role="alert"></p>';const command=crypto.randomUUID();let busy=false;const modal=AdvaconUI.modal({title:tr('تمديد عهدة','Extend custody'),body,footer});footer.append(btn(tr('حفظ التمديد','Save extension'),async()=>{if(busy)return;const due=body.querySelector('input');if(!due.reportValidity())return;if(due.value<=current){body.querySelector('[role=alert]').textContent=friendly(Error('extension_date_must_increase'));return;}busy=true;modal.setBusy(true);footer.querySelector('button').disabled=true;try{const r=await raw('advacon_warehouse_custody_extend',{p_command_id:command,p_document_id:id,p_return_due_date:due.value,p_note:body.querySelector('textarea').value||null});modal.setBusy(false);modal.markClean();modal.close();invalidate();openDocument(r.id);}catch(e){body.querySelector('[role=alert]').textContent=friendly(e);}finally{busy=false;modal.setBusy(false);footer.querySelector('button').disabled=false;}},true));}catch(e){toast(friendly(e),'error');}}
async function reviewExtension(data){const body=document.createElement('div'),footer=document.createElement('div');body.className='wd-form';body.innerHTML=documentHTML(data)+'<label>'+tr('موعد الإرجاع الجديد','New return date')+'<input type="date" value="'+h(data.document.return_due_date)+'"></label><label>'+tr('ملاحظة السند','Voucher note')+'<textarea>'+h(data.document.note||'')+'</textarea></label><p class="wd-error" role="alert"></p>';let busy=false;const modal=AdvaconUI.modal({title:tr('اعتماد التمديد','Approve extension'),body,footer,wide:true});footer.append(btn(tr('اعتماد','Approve'),async()=>{if(busy)return;busy=true;modal.setBusy(true);footer.querySelector('button').disabled=true;try{await raw('advacon_warehouse_document_review_v2',{p_id:data.document.id,p_version:data.document.version,p_decision:'approve',p_lines:null,p_note:null,p_metadata:{employee_id:data.document.employee_id,project_id:data.document.project_id,return_due_date:body.querySelector('input').value||null,note:body.querySelector('textarea').value||null}});modal.setBusy(false);modal.markClean();modal.close();invalidate();openDocument(data.document.id);}catch(e){body.querySelector('[role=alert]').textContent=friendly(e);}finally{busy=false;modal.setBusy(false);footer.querySelector('button').disabled=false;}},true));}
