aprStartEdit=async function(id){const r=(aprList||[]).find(x=>x.id===id);if(!r||aprIsOwn(r))return;try{const o=await raw('advacon_warehouse_document_options',{p_kind:r.movement_type}),a={p_item_id:r.orig_item_id,p_item_warehouse_id:r.orig_item_warehouse_id,p_warehouse_id:r.orig_warehouse_id,p_qty:r.orig_qty,p_shelf_id:r.orig_shelf_id,p_dest_warehouse_id:r.orig_dest_warehouse_id,p_dest_shelf_id:r.orig_dest_shelf_id,p_expiry_date:r.orig_expiry_date,p_batch_no:r.orig_batch_no,p_note:r.orig_note,p_direction:r.orig_direction,p_reason_category:r.orig_reason_category,p_ref_issue_movement_id:r.orig_ref_movement_id};const snap=lineSnapshot(o,a);await openForm(r.movement_type,null,null,{legacy_id:id,document:{note:r.orig_note},lines:snap.item_id?[{line_no:1,args:a,snapshot:snap}]:[]});}catch(e){toast(friendly(e),'error');}};

